-- Catalogue gap report: ALL FIVE QUERIES IN ONE (READ-ONLY)
--
-- GENERATED by scripts/catalogue-gap/build-sql.mjs from 1_summary.sql ...
-- 5_work.sql. Edit those, not this file.
--
-- Run once in the staging project's SQL editor and once in production's.
-- Download each result as CSV. Output columns: part, chunk, items, payload.
-- Same safety and content as the five separate queries: the session is set
-- read-only first, the only non-SELECT statements store results in temporary
-- session settings, and nothing is written to any table or file.
-- See docs/catalogue-sync/GAP-REPORT.md.

set default_transaction_read_only = on;

-- 1. Summary
do $$
declare
  out jsonb := '{}'::jsonb;
  v jsonb;
  markers jsonb := '{}'::jsonb;
  m record;
begin
  -- Which project this is (marker from 073_RUNBOOK.md), if it exists.
  if to_regprocedure('public.pinhunt_environment()') is not null then
    execute 'select to_jsonb(public.pinhunt_environment())' into v;
    out := out || jsonb_build_object('environment', v);
  else
    out := out || jsonb_build_object('environment', null);
  end if;
  out := out || jsonb_build_object('generated_at', now(), 'report_version', 1);

  -- Migrations 037 onwards, each detected by an object it creates. Five
  -- migrations only rewrite existing functions or grants (056, 061, 063, 064,
  -- 074) and can't be detected this way: use their supabase/verify scripts.
  for m in
    select * from (values
      ('037', 'table', 'catalogue_sources'),
      ('038', 'column', 'pin_images.status'),
      ('039', 'table', 'feature_flags'),
      ('040', 'function', 'is_app_creator'),
      ('041', 'policy', 'pins.pins_app_creator_insert'),
      ('042', 'constraint', 'pin_images_pin_and_pop_reference_only'),
      ('043', 'table', 'user_boards'),
      ('044', 'function', 'set_user_pin_statuses'),
      ('045', 'function', 'next_pinhunt_id'),
      ('047', 'table', 'contributor_ai_usage'),
      ('048', 'function', 'get_catalogue_image_coverage'),
      ('049', 'table', 'market_sources'),
      ('050', 'table', 'user_blocks'),
      ('051', 'table', 'account_deletions'),
      ('052', 'table', 'catalogue_review_events'),
      ('053', 'column', 'pin_external_ids.match_status'),
      ('054', 'column', 'market_listings.site'),
      ('055', 'table', 'market_valuation_history'),
      ('057', 'column', 'trades.initiator_posted_at'),
      ('058', 'constraint', 'trade_ratings_comment_length'),
      ('059', 'column', 'trades.problem_reason'),
      ('060', 'function', 'link_conversation_trade'),
      ('062', 'function', 'get_my_postcode'),
      ('065', 'table', 'collector_pin_prices'),
      ('066', 'function', 'collector_contact_preferences'),
      ('067', 'table', 'collection_places'),
      ('068', 'column', 'profiles.home_market'),
      ('069', 'column', 'contributor_ai_usage.outcome'),
      ('070', 'column', 'trades.items_version'),
      ('071', 'function', 'trade_post_event'),
      ('072', 'table', 'message_moderation_events'),
      ('073', 'function', 'pinhunt_minimum_age'),
      ('075', 'table', 'board_scans'),
      ('076', 'table', 'bulk_image_batches')
    ) as t(migration, kind, name)
  loop
    markers := markers || jsonb_build_object(m.migration, case m.kind
      when 'table' then to_regclass('public.' || m.name) is not null
      when 'function' then exists (
        select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public' and p.proname = m.name)
      when 'constraint' then exists (select 1 from pg_constraint where conname = m.name)
      when 'policy' then exists (
        select 1 from pg_policies
        where schemaname = 'public' and tablename = split_part(m.name, '.', 1)
          and policyname = split_part(m.name, '.', 2))
      when 'column' then exists (
        select 1 from information_schema.columns
        where table_schema = 'public'
          and table_name = split_part(m.name, '.', 1)
          and column_name = split_part(m.name, '.', 2))
    end);
  end loop;
  -- 073's project marker, which later migrations' guards rely on.
  markers := markers || jsonb_build_object('073_marker', to_regprocedure('public.pinhunt_environment()') is not null);
  out := out || jsonb_build_object('migration_markers', markers);

  -- Pins: totals and statuses (to_jsonb keeps this independent of columns).
  select jsonb_build_object(
    'total', count(*),
    'by_verification_status', coalesce((select jsonb_object_agg(k, n) from (
        select coalesce(to_jsonb(p)->>'verification_status', '(none)') k, count(*) n
        from public.pins p group by 1) s), '{}'),
    'by_catalogue_status', coalesce((select jsonb_object_agg(k, n) from (
        select coalesce(to_jsonb(p)->>'catalogue_status', '(none)') k, count(*) n
        from public.pins p group by 1) s), '{}'),
    'searchable', count(*) filter (where (to_jsonb(p)->>'is_searchable') = 'true'),
    'with_image_url', count(*) filter (where p.image_url is not null),
    'with_back_image_url', count(*) filter (where p.back_image_url is not null),
    'max_pinhunt_id', max(p.pinhunt_id),
    'last_created_at', max(p.created_at),
    'last_updated_at', max(p.updated_at)
  ) into v from public.pins p;
  out := out || jsonb_build_object('pins', v);

  -- Where pin photos are hosted: project ref + bucket, or "other".
  select coalesce(jsonb_object_agg(host, n), '{}') into v from (
    select coalesce(substring(u from '^https://([a-z0-9]{20})\.supabase\.co/storage/v1/object/public/[^/]+')
                    || ':' || substring(u from '^https://[a-z0-9]{20}\.supabase\.co/storage/v1/object/public/([^/]+)/'),
                    case when u ~ '^https?://' then 'other:' || substring(u from '^https?://([^/]+)') else 'relative_or_invalid' end) host,
           count(*) n
    from (select image_url u from public.pins where image_url is not null
          union all select back_image_url from public.pins where back_image_url is not null) x
    group by 1) s;
  out := out || jsonb_build_object('pin_image_hosts', v);

  -- pin_images by source / status / public display. Pin & Pop counted only.
  select coalesce(jsonb_agg(jsonb_build_object(
      'source', src, 'status', st, 'public_display_allowed', pda,
      'contributed', contributed, 'count', n) order by src, st), '[]') into v
  from (
    select coalesce(to_jsonb(i)->>'source', '(none)') src,
           coalesce(to_jsonb(i)->>'status', '(none)') st,
           to_jsonb(i)->>'public_display_allowed' pda,
           i.uploaded_by is not null contributed,
           count(*) n
    from public.pin_images i group by 1, 2, 3, 4) s;
  out := out || jsonb_build_object('pin_images', v);

  -- External id links by source (no ids listed).
  select coalesce(jsonb_object_agg(src, n), '{}') into v from (
    select coalesce(to_jsonb(e)->>'source', '(none)') src, count(*) n
    from public.pin_external_ids e group by 1) s;
  out := out || jsonb_build_object('pin_external_ids', v);

  -- Rights flags per catalogue source (no secrets here; these are policy rows).
  if to_regclass('public.catalogue_sources') is not null then
    execute $q$
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', id,
        'public_display_allowed', to_jsonb(c)->'public_display_allowed',
        'storage_allowed', to_jsonb(c)->'storage_allowed',
        'app_use_allowed', to_jsonb(c)->'app_use_allowed',
        'attribution_required', to_jsonb(c)->'attribution_required',
        'exact_license_variant', to_jsonb(c)->'exact_license_variant',
        'rights_basis', to_jsonb(c)->'rights_basis',
        'updated_at', to_jsonb(c)->'updated_at') order by id), '[]')
      from public.catalogue_sources c $q$ into v;
    out := out || jsonb_build_object('catalogue_sources', v);
  end if;

  -- Other catalogue tables: row counts.
  select jsonb_build_object(
    'pin_sets', (select count(*) from public.pin_sets),
    'characters', (select count(*) from public.characters),
    'categories', (select count(*) from public.categories),
    'pin_set_memberships', (select count(*) from public.pin_set_memberships),
    'pin_characters', (select count(*) from public.pin_characters)
  ) into v;
  out := out || jsonb_build_object('catalogue_tables', v);

  -- Work queues: counts only (details are in query 5).
  select coalesce(jsonb_object_agg(status, n), '{}') into v from (
    select status, count(*) n from public.pin_submissions group by 1) s;
  out := out || jsonb_build_object('pin_submissions', v);

  if to_regclass('public.board_scans') is not null then
    execute $q$ select jsonb_build_object(
      'boards', (select coalesce(jsonb_object_agg(status, n), '{}') from (select status, count(*) n from public.board_scans group by 1) s),
      'items', (select count(*) from public.board_scan_items),
      'items_published', (select count(*) from public.board_scan_items where pin_image_id is not null)) $q$ into v;
    out := out || jsonb_build_object('board_scans', v);
  end if;

  if to_regclass('public.bulk_image_batches') is not null then
    execute $q$ select jsonb_build_object(
      'batches', (select count(*) from public.bulk_image_batches),
      'items', (select coalesce(jsonb_object_agg(status, n), '{}') from (select status, count(*) n from public.bulk_image_items group by 1) s),
      'items_published', (select count(*) from public.bulk_image_items where published_pin_image_id is not null)) $q$ into v;
    out := out || jsonb_build_object('bulk_images', v);
  end if;

  if to_regclass('public.catalogue_candidates') is not null then
    execute $q$ select coalesce(jsonb_object_agg(status, n), '{}')
      from (select status, count(*) n from public.catalogue_candidates group by 1) s $q$ into v;
    out := out || jsonb_build_object('catalogue_candidates', v);
  end if;

  -- Storage: files and bytes per bucket.
  select coalesce(jsonb_agg(jsonb_build_object(
      'bucket', b.id, 'public', b.public,
      'objects', (select count(*) from storage.objects o where o.bucket_id = b.id),
      'bytes', (select coalesce(sum((o.metadata->>'size')::bigint), 0) from storage.objects o where o.bucket_id = b.id))
    order by b.id), '[]') into v
  from storage.buckets b;
  out := out || jsonb_build_object('storage_buckets', v);

  perform set_config('pinhunt.gap_summary', out::text, false);
end $$;

-- 5. Work in progress
do $$
declare
  out jsonb := '{}'::jsonb;
  v jsonb;
begin
  -- New-pin submissions (drafts counted only: they are unfinished personal work).
  select jsonb_build_object(
    'draft_count', (select count(*) from public.pin_submissions where status = 'draft'),
    'items', coalesce(jsonb_agg(jsonb_build_object(
        'id', s.id,
        'status', s.status,
        'created_at', s.created_at,
        'updated_at', to_jsonb(s)->'updated_at',
        'has_front_photo', to_jsonb(s)->>'front_image_path' is not null,
        'has_back_photo', to_jsonb(s)->>'back_image_path' is not null,
        'approved_pin_id', to_jsonb(s)->'approved_pin_id',
        'approved_pinhunt_id', p.pinhunt_id,
        'proposed_name', to_jsonb(s)->'proposed_name',
        'series_name', to_jsonb(s)->'series_name',
        'release_year', to_jsonb(s)->'release_year',
        'rights_confirmed', to_jsonb(s)->>'rights_confirmed_at' is not null)
      order by s.created_at), '[]'))
  into v
  from public.pin_submissions s
  left join public.pins p on p.id = (to_jsonb(s)->>'approved_pin_id')::uuid
  where s.status <> 'draft';
  out := out || jsonb_build_object('pin_submissions', v);

  if to_regclass('public.board_scans') is not null then
    execute $q$
      select jsonb_build_object(
        'boards', (select coalesce(jsonb_agg(jsonb_build_object(
            'id', b.id, 'status', b.status, 'mode', to_jsonb(b)->'mode', 'title', b.title,
            'permission_basis', b.permission_basis,
            'permission_public_display', b.permission_public_display,
            'not_third_party_catalogue', b.not_third_party_catalogue,
            'created_at', b.created_at, 'updated_at', b.updated_at,
            'stats', b.stats) order by b.created_at), '[]') from public.board_scans b),
        'items', (select coalesce(jsonb_agg(jsonb_build_object(
            'id', i.id, 'board_scan_id', i.board_scan_id, 'position', i.position, 'origin', i.origin,
            'match_status', i.match_status, 'suggested_pinhunt_id', i.suggested_pin_id,
            'match_confidence', i.match_confidence, 'decision', i.decision,
            'decided_pinhunt_id', i.decided_pin_id, 'exclude_reason', i.exclude_reason,
            'cleanup_status', i.cleanup_status, 'has_crop', i.crop_path is not null,
            'has_cleaned_photo', i.cleaned_path is not null, 'image_review', i.image_review,
            'pin_image_id', i.pin_image_id, 'updated_at', to_jsonb(i)->'updated_at')
          order by i.board_scan_id, i.position), '[]') from public.board_scan_items i)) $q$
    into v;
    out := out || jsonb_build_object('board_scans', v);
  end if;

  if to_regclass('public.bulk_image_batches') is not null then
    execute $q$
      select jsonb_build_object(
        'batches', (select coalesce(jsonb_agg(jsonb_build_object(
            'id', b.id, 'title', b.title, 'status', b.status, 'supplier_name', b.supplier_name,
            'permission_basis', b.permission_basis, 'licence', b.licence,
            'permission_public_display', b.permission_public_display,
            'created_at', b.created_at) order by b.created_at), '[]') from public.bulk_image_batches b),
        'items', (select coalesce(jsonb_agg(jsonb_build_object(
            'id', i.id, 'batch_id', i.batch_id, 'status', i.status, 'failed_stage', i.failed_stage,
            'match_band', i.match_band, 'match_verified', i.match_verified,
            'matched_pinhunt_id', i.matched_pinhunt_id, 'match_method', i.match_method,
            'confirmed', i.confirmed_at is not null,
            'has_cleaned_photo', i.cleaned_path is not null,
            'published_pin_image_id', i.published_pin_image_id,
            'published_image_url', i.published_image_url,
            'replaced_image_url', i.replaced_image_url,
            'published_at', i.published_at, 'updated_at', i.updated_at)
          order by i.batch_id, i.created_at), '[]') from public.bulk_image_items i)) $q$
    into v;
    out := out || jsonb_build_object('bulk_images', v);
  end if;

  if to_regclass('public.catalogue_candidates') is not null then
    execute $q$
      select jsonb_build_object(
        'by_status', (select coalesce(jsonb_object_agg(status, n), '{}')
                        from (select status, count(*) n from public.catalogue_candidates group by 1) s),
        'runs', (select count(*) from public.catalogue_research_runs)) $q$
    into v;
    out := out || jsonb_build_object('catalogue_candidates', v);
  end if;

  perform set_config('pinhunt.gap_work', out::text, false);
end $$;

-- Everything as one result: summary and work as one row each; pins, photos
-- and files in chunks of 500 records per row.
select part, chunk, items, payload
from (
  select 'summary'::text as part, 1::bigint as chunk, 1::bigint as items,
         current_setting('pinhunt.gap_summary') as payload
  union all
  select 'work', 1, 1, current_setting('pinhunt.gap_work')
  union all
  select 'pins', q.* from (
    with p as (
      select p.id, p.pinhunt_id, p.image_url, p.back_image_url, p.created_at, p.updated_at,
             to_jsonb(p) as j
      from public.pins p
    ),
    scrubbed as (
      select p.*,
        (select coalesce(jsonb_object_agg(k, case
                  when k = 'external_identifiers' and jsonb_typeof(val) = 'object' then
                    (select coalesce(jsonb_object_agg(ek, ev), '{}'::jsonb) from jsonb_each(val) as e(ek, ev)
                      where regexp_replace(lower(ek), '[^a-z]', '', 'g') not like '%pinandpop%'
                        and regexp_replace(lower(ek), '[^a-z]', '', 'g') not like '%pinpop%')
                  else val end), '{}'::jsonb)
           from jsonb_each(p.j) as x(k, val)
          where k not in ('id', 'pinhunt_id', 'created_at', 'updated_at', 'catalogue_updated_at',
                          'raw_import_data', 'import_batch_id', 'image_url', 'back_image_url',
                          'needs_front_image', 'needs_back_image',
                          'submitted_by', 'uploaded_by', 'reviewed_by', 'created_by', 'updated_by',
                          'imported_by', 'changed_by', 'approved_by', 'confirmed_by', 'user_id', 'owner_id')
            and k !~ '(tsv|fts|search_vector|search_document)$'
        ) as content
      from p
    ),
    records as (
      select
        s.pinhunt_id,
        s.id,
        s.j->>'verification_status' as verification_status,
        s.j->>'catalogue_status' as catalogue_status,
        s.j->>'is_searchable' as is_searchable,
        s.j->>'title' as title,
        s.j->>'collection' as collection,
        s.j->>'normalised_series' as normalised_series,
        s.j->>'release_year' as release_year,
        s.j->>'edition_type' as edition_type,
        s.image_url,
        s.back_image_url,
        s.created_at,
        s.updated_at,
        (select string_agg(e.source || ':' || e.external_id, ';' order by e.source, e.external_id)
           from public.pin_external_ids e
          where e.pin_id = s.id
            and regexp_replace(lower(e.source), '[^a-z]', '', 'g') not in ('pinandpop', 'pinpop')) as external_ids,
        exists (select 1 from public.pin_external_ids e
                 where e.pin_id = s.id
                   and regexp_replace(lower(e.source), '[^a-z]', '', 'g') in ('pinandpop', 'pinpop')) as has_pin_and_pop_link,
        md5(s.content::text) as content_md5,
        case when coalesce(s.j->>'catalogue_status', '') <> 'archived' then s.content::text end as content
      from scrubbed s
    ),
    numbered as (
      select r, row_number() over (order by r.pinhunt_id) as rn from records r
    )
    select
      (rn - 1) / 500 + 1 as chunk,
      count(*) as pins_in_chunk,
      json_agg(r order by rn)::text as pins_json
    from numbered
    group by 1
  ) q
  union all
  select 'images', q.* from (
    with i as (
      select i.*, to_jsonb(i) as j,
             regexp_replace(lower(coalesce(to_jsonb(i)->>'source', '')), '[^a-z]', '', 'g') in ('pinandpop', 'pinpop') as is_pnp
      from public.pin_images i
    ),
    records as (
      select
        i.id,
        p.pinhunt_id,
        i.pin_id,
        i.image_type,
        i.j->>'source' as source,
        case when i.is_pnp then null else i.j->>'source_record_id' end as source_record_id,
        i.j->>'status' as status,
        i.j->>'public_display_allowed' as public_display_allowed,
        i.is_primary,
        case when i.is_pnp then null else i.j->>'content_hash' end as content_hash,
        case when i.is_pnp then null else i.image_url end as image_url,
        (i.uploaded_by is not null) as contributed,
        i.j->>'proposal_reason' as proposal_reason,
        i.created_at,
        i.j->>'reviewed_at' as reviewed_at,
        (p.image_url is not distinct from i.image_url and not i.is_pnp) as is_pin_front_photo,
        (p.back_image_url is not distinct from i.image_url and not i.is_pnp) as is_pin_back_photo
      from i
      left join public.pins p on p.id = i.pin_id
    ),
    numbered as (
      select r, row_number() over (order by r.pinhunt_id, r.created_at, r.id) as rn from records r
    )
    select
      (rn - 1) / 500 + 1 as chunk,
      count(*) as images_in_chunk,
      json_agg(r order by rn)::text as images_json
    from numbered
    group by 1
  ) q
  union all
  select 'files', q.* from (
    with records as (
      select
        o.bucket_id,
        -- Private buckets file uploads under account ids, so their names are hashed.
        case when o.bucket_id = 'pin-catalogue' then o.name else 'hashed:' || md5(o.name) end as name,
        (o.metadata->>'size')::bigint as size,
        o.metadata->>'eTag' as etag,
        o.metadata->>'mimetype' as mimetype,
        o.created_at,
        o.updated_at
      from storage.objects o
      where o.bucket_id in ('pin-catalogue', 'pin-contributed-images', 'board-scans', 'bulk-image-matcher')
    ),
    numbered as (
      select r, row_number() over (order by r.bucket_id, r.name) as rn from records r
    )
    select
      (rn - 1) / 500 + 1 as chunk,
      count(*) as files_in_chunk,
      json_agg(r order by rn)::text as files_json
    from numbered
    group by 1
  ) q
) all_parts
order by case part when 'summary' then 1 when 'work' then 2 when 'pins' then 3 when 'images' then 4 else 5 end, chunk;
